Definition LIT_CHUNKED : list Z := [99; 104; 117; 110; 107; 101; 100].
Definition LIT_CLOSE : list Z := [99; 108; 111; 115; 101].
Definition LIT_KEEPALIVE : list Z := [107; 101; 101; 112; 45; 97; 108; 105; 118; 101].
Definition LIT_UPGRADE : list Z := [117; 112; 103; 114; 97; 100; 101].
Definition A_CHUNKED : Z := 0x1172a. Definition A_CLOSE : Z := 0x11d1e. Definition A_KEEPALIVE : Z := 0x10430. Definition A_UPGRADE : Z := 0x140c2.
Definition litb (l : list Z) : list byte := map (fun z => Z_to_bv 8 z) l.

Definition OptU64Cells (b : bool) (pad : list byte) (v : word) : list cell := [C1 (b8 (Z.b2z b)); CB 7 pad; C8 v].

(* [comment removed for export] *)
Ltac bload H q :=
  lazymatch type of H with bytes_at _ ?mx ?it0 ?bs =>
    let b := fresh "b" in let N := fresh "N" in let RD := fresh "RD" in let BR := fresh "BR" in
    destruct (win_byte _ _ _ q H ltac:(lia)) as [b N];
    pose proof (zb_range b) as BR; unfold zb in BR;
    pose proof (u8ro_read usegs _ it0 bs (q - it0) b (Z_to_bv 64 q) H N ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD; change (zxb b) with (Z_to_bv 64 (zb b)); fold (zb b) in BR
  end.

(* [comment removed for export] *)
Ltac blob2 H1 H2 :=
  let j1 := fresh "jb" in let j2 := fresh "jb" in let B1 := fresh "BL" in let B2 := fresh "BL" in
  destruct (rw_cells_forget _ _ _ _ H1) as [j1 B1]; destruct (rw_cells_forget _ _ _ _ H2) as [j2 B2]; clear H1 H2;
  cbn [cells_size csize Nat.add TokItCells OptItCells OptU64Cells map] in B1, B2;
  lazymatch type of B1 with rw_cells _ _ ?a1 [CB ?n1 _] =>
    lazymatch type of B2 with rw_cells _ _ ?a2 _ =>
      replace a2 with (a1 + Z.of_nat n1) in B2 by lia;
      pose proof (rw_cells_CB_join usegs _ _ _ _ _ _ B1 B2) as H1; clear B1 B2; cbn [Nat.add] in H1
    end end.

