Lemma lit_close_bytes : forall m, mem_inv usegs m -> bytes_at usegs m A_CLOSE (litb LIT_CLOSE).
Proof.
  intros m MI. apply (ro_cells_bytes_at usegs m A_CLOSE [CB 5 (litb LIT_CLOSE)]).
  apply (ro_cells_image usegs m); [exact MI | vm_compute; reflexivity | unfold A_CLOSE; lia | cbn; unfold A_CLOSE; lia].
Qed.
