Lemma lit_upgrade_bytes : forall m, mem_inv usegs m -> bytes_at usegs m A_UPGRADE (litb LIT_UPGRADE).
Proof.
  intros m MI. apply (ro_cells_bytes_at usegs m A_UPGRADE [CB 7 (litb LIT_UPGRADE)]).
