Definition P_UB_OPT_MOVE : Z := 0x40098.
Definition OPTMV_STACK : Z := 16.


Definition optmv_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (A R : Z) (hb rb : bool) (padA padR : list byte) (va vr : word) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (A, A + 16)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' A (OptU64Cells rb padA (if rb then vr else va))
    /\ rw_cells usegs m' R (OptU64Cells rb padR vr).

Definition optmv_stmt : Prop :=
  forall (A R : Z) (hb rb : bool) (padA padR : list byte) (va vr : word) (lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells usegs m A (OptU64Cells hb padA va) ->
  rw_cells usegs m R (OptU64Cells rb padR vr) ->
  (A + 16 <= R \/ R + 16 <= A) ->
  stk usegs m lo (bv_unsigned sp) -> lo + OPTMV_STACK <= bv_unsigned sp -> 0xb8000 <= lo ->
  bv_unsigned sp <= A -> A + 16 < 2^64 -> bv_unsigned sp <= R -> R + 16 < 2^64 ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
