(* [comment removed for export] *)
(* [comment removed for export] *)
Definition P_UB_DOF_FINDIF : Z := 0x4011c.
Definition DOF_FINDIF_STACK : Z := 144.          (* [comment removed for export] *)

(* [comment removed for export] *)
Definition tok_inv (vp La vq vl itv fv : Z) : Prop :=
  (vq = 0 /\ vl = 0 /\ itv = La /\ fv = La)
  \/ (vp <= vq /\ 0 <= vl /\ vq + vl <= itv /\ itv <= La /\ vp <= fv /\ fv < itv).

Lemma tok_inv_after : forall r it La, it <= La ->
  (forall k l, r = TK_tok k l -> it + Z.of_nat k + Z.of_nat l <= La /\ (1 <= l)%nat) ->
  exists vq vl itv fv, tokit_cells_after r it La = TokItCells vq vl itv fv La
    /\ ((vq = 0 /\ vl = 0 /\ itv = La /\ fv = La) \/ (it <= vq /\ 0 <= vl /\ vq + vl <= itv /\ itv <= La /\ fv = it /\ fv < itv)).
Proof.
  intros r it La H2 HR. destruct r as [| |k l].
  - exists 0, 0, La, La. split; [reflexivity|]. left; repeat split; reflexivity.
  - exists 0, 0, La, La. split; [reflexivity|]. left; repeat split; reflexivity.
  - destruct (HR k l eq_refl) as [B L]. exists (it + Z.of_nat k), (Z.of_nat l), (it + Z.of_nat k + Z.of_nat l), it.
    split; [reflexivity|]. right; repeat split; lia.
Qed.

Definition dfi_post_r (vq vl itv fv : Z) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (R IT EA vp : Z) (vbs : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (R, R + SZ_TOKIT); (IT, IT + SZ_TOKIT)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' R (TokItCells vq vl itv fv (vp + Z.of_nat (length vbs)))
    /\ rw_cells usegs m' IT (TokItCells vq vl itv fv (vp + Z.of_nat (length vbs)))
    /\ rw_cells usegs m' EA (TokItCells 0 0 (vp + Z.of_nat (length vbs)) (vp + Z.of_nat (length vbs)) (vp + Z.of_nat (length vbs)))
    /\ bytes_at usegs m' vp vbs.

Definition dof_findif_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (R IT EA vp : Z) (vbs : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (vq vl itv fv : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (R, R + SZ_TOKIT); (IT, IT + SZ_TOKIT)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' R (TokItCells vq vl itv fv (vp + Z.of_nat (length vbs)))
