Definition dof_findif_stmt : Prop :=
  forall (R IT EA vp : Z) (vbs : list byte) (rjunk : list cell) (vq vl itv fv : Z) (lo hi : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells usegs m R rjunk -> cells_size rjunk = 40%nat ->
  rw_cells usegs m IT (TokItCells vq vl itv fv (vp + Z.of_nat (length vbs))) ->
  tok_inv vp (vp + Z.of_nat (length vbs)) vq vl itv fv ->
  rw_cells usegs m EA (TokItCells 0 0 (vp + Z.of_nat (length vbs)) (vp + Z.of_nat (length vbs)) (vp + Z.of_nat (length vbs))) ->
  bytes_at usegs m vp vbs -> vp + Z.of_nat (length vbs) < 2^64 ->
  stk usegs m lo (bv_unsigned sp) -> lo + DOF_FINDIF_STACK <= bv_unsigned sp -> 0xb8000 <= lo ->
  (* [comment removed for export] *)
  bv_unsigned sp <= EA -> EA + SZ_TOKIT <= IT -> IT + SZ_TOKIT <= R -> R + SZ_TOKIT <= hi ->
  (hi <= vp \/ vp + Z.of_nat (length vbs) <= lo) ->
  ((0 < length vbs)%nat -> 0 < vp) ->                                            (* [comment removed for export] *)
  IT mod 8 = 0 -> EA mod 8 = 0 ->                                               (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (dof_findif_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R IT EA vp vbs lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz R) (wz IT) (wz EA) a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_UB_DOF_FINDIF) fc None m (seg_rom usegs)).

(* [comment removed for export] *)
Definition dfi_ctx (m m1 : mem) (sp s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word) (R IT EA vp : Z) (vbs : list byte)
    (lo : Z) (junkR : list byte) (itc : list cell) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -80) [C8 s8v; C8 s7v; C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells usegs m1 R [CB 40 junkR]
  /\ rw_cells usegs m1 IT itc
  /\ rw_cells usegs m1 EA (TokItCells 0 0 (vp + Z.of_nat (length vbs)) (vp + Z.of_nat (length vbs)) (vp + Z.of_nat (length vbs)))
  /\ bytes_at usegs m1 vp vbs
  /\ stk usegs m1 lo (bv_unsigned sp + -80)
  /\ munch [(lo, bv_unsigned sp); (R, R + SZ_TOKIT); (IT, IT + SZ_TOKIT)]%Z m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

Definition dfi_pure (sp : word) (R IT EA vp : Z) (vbs : list byte) (lo hi : Z) : Prop :=
  vp + Z.of_nat (length vbs) < 2^64
  /\ lo + DOF_FINDIF_STACK <= bv_unsigned sp /\ 0xb8000 <= lo
  /\ bv_unsigned sp <= EA /\ EA + SZ_TOKIT <= IT /\ IT + SZ_TOKIT <= R /\ R + SZ_TOKIT <= hi
  /\ (hi <= vp \/ vp + Z.of_nat (length vbs) <= lo)
  /\ ((0 < length vbs)%nat -> 0 < vp)
  /\ IT mod 8 = 0 /\ EA mod 8 = 0.

Local Ltac open_dctx CTX PURE :=
  lazymatch type of CTX with dfi_ctx _ _ ?sp _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ =>
  destruct CTX as (FR & RJ & ITC & EAC & WS & ST & MU & WM & MI);
  destruct PURE as (SP64 & LO & L98 & LEA & LIT & LR & LHI & SS & NZS & ITAL & EAAL);
  pose proof (bytes_at_bound _ _ _ _ WS) as WSB;
  pose proof (rw_cells_bound _ _ _ _ RJ) as RB; cbn [cells_size csize Nat.add length] in RB;
  pose proof (rw_cells_bound _ _ _ _ EAC) as EAB; cbn [cells_size csize Nat.add length TokItCells] in EAB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold TokItCells, SZ_TOKIT, DOF_FINDIF_STACK in * end.

Local Ltac rebuild_dctx m sp R IT EA vp :=
  try match goal with C : dfi_ctx _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ => clear C end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | FR : rw_cells _ mx (bv_unsigned sp + -80) [C8 ?s8v; C8 ?s7v; C8 ?s6v; C8 ?s5v; C8 ?s4v; C8 ?s3v; C8 ?s2v; C8 ?s1v; C8 ?s0v; C8 ?rav],
    RJ : rw_cells _ mx R [CB 40 ?junkR], ITC : rw_cells _ mx IT ?itc, EAC : rw_cells _ mx EA _,
    WS : bytes_at _ mx vp ?vbs, ST : stk _ mx ?lo _,
    MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx |- _ =>
      let CTX := fresh "CTX" in
      assert (CTX : dfi_ctx m mx sp s8v s7v s6v s5v s4v s3v s2v s1v s0v rav R IT EA vp vbs lo junkR itc)
        by (split; [exact FR | split; [exact RJ | split; [exact ITC | split; [exact EAC | split; [exact WS |
            split; [exact ST | split; [exact MU | split; [exact WM | exact MI]]]]]]]])
  end end.

(* [comment removed for export] *)
Lemma dfi_done : forall (vq vl itv fv : Z) rax a0x a1x a2x a3x a4x a5x a6x a7x ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (R IT EA vp : Z) (vbs : list byte) (lo hi : Z) (junkR : list byte),
  dfi_ctx m m1 sp s8 s7 s6 s5 s4 s3 s2 s1 s0 ra R IT EA vp vbs lo junkR (TokItCells vq vl itv fv (vp + Z.of_nat (length vbs))) ->
  dfi_pure sp R IT EA vp vbs lo hi ->
  evt usegs (dfi_post_r vq vl itv fv ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R IT EA vp vbs lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 (wz IT) (wz R) a0x a1x a2x a3x a4x a5x a6x a7x
              (wz EA) (wz 7) (wz 1) (wz 2) (Z_to_bv 64 (-6)) (wz A_CHUNKED) (Z_to_bv 64 (-1)) s9 s10 s11 t3 t4 t5 t6)
