(* [comment removed for export] *)
Definition dfi_cont (Q : machine_state -> Prop) (pc : Z) rax spx gp tp t0 t1 t2 s0 s1 s2 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) : Prop :=
  forall a0' a1' a2' a3' a4' a5' a6' a7',
    evt usegs Q (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 (wz 7) (wz 1) (wz 2) (Z_to_bv 64 (-6)) (wz A_CHUNKED) (Z_to_bv 64 (-1)) s9 s10 s11 t3 t4 t5 t6)
                    F (Z_to_bv 64 pc) fc None m1 (seg_rom usegs)).

(* [comment removed for export] *)
Lemma dfi_slow : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (VQ vp : Z) (vbs : list byte),
  (7 - j = k)%nat -> (j < 7)%nat ->
  bytes_at usegs m1 vp vbs -> bytes_at usegs m1 A_CHUNKED (litb LIT_CHUNKED) ->
  vp <= VQ -> VQ + 7 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 -> 0 < vp ->
  mem_inv usegs m1 ->
  dfi_cont Q 0x40264 rax spx gp tp t0 t1 t2 s0 s1 s2 s9 s10 s11 t3 t4 t5 t6 F fc m1 ->
