Local Ltac call_incr A vp vl it fst La W wbs lo :=
  let S := fresh "IS" in
  pose proof tokit_incr_spec as S;
  unfold tokit_incr_stmt, tokit_incr_post, SZ_TOKIT, TOKIT_STACK, P_TOKEN_LIST_ITER_INCR in S;
  callZ (S A vp vl it fst La W wbs lo);
  [ assumption | assumption | lia | lia | lia | lia | lia
  | rewrite ?unsigned_lit by lia; assumption | rewrite ?unsigned_lit by lia; lia | lia
  | rewrite ?unsigned_lit by lia; lia | rewrite ?unsigned_lit by lia; lia
  | assumption | assumption | clear S ].
